#!/bin/bash
set -euo pipefail

#
# AZ PANEL - Self-contained installer
# A self-hosted Minecraft/VPS management panel
#
# Usage:
#   chmod +x az-panel.sh
#   sudo ./az-panel.sh install
#
# Commands:
#   install    - Install AZ PANEL
#   uninstall  - Remove AZ PANEL
#   start      - Start the panel
#   stop       - Stop the panel
#   restart    - Restart the panel
#   status     - Check if panel is running
#   logs       - View panel logs
#   update     - Update panel (re-run with new script)
#

# ============================================================================
# Configuration
# ============================================================================
AZ_PANEL_DIR="/opt/az-panel"
AZ_PANEL_DATA="${AZ_PANEL_DIR}/data"
AZ_PANEL_LOG="/var/log/az-panel"
AZ_PANEL_PID="${AZ_PANEL_DIR}/az-panel.pid"
AZ_PANEL_USER="azpanel"
AZ_PANEL_PORT="${AZ_PANEL_PORT:-7777}"
AZ_PANEL_VERSION="1.0.0"
NODE_MIN_VERSION="18"

# Colors
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
NC='\033[0m' # No Color

# ============================================================================
# Helper functions
# ============================================================================
info()  { echo -e "${CYAN}[INFO]${NC} $*"; }
ok()    { echo -e "${GREEN}[OK]${NC} $*"; }
warn()  { echo -e "${YELLOW}[WARN]${NC} $*"; }
error() { echo -e "${RED}[ERROR]${NC} $*" >&2; }

check_root() {
    if [[ $EUID -ne 0 ]]; then
        error "This script must be run as root (use sudo)."
        exit 1
    fi
}

get_distro() {
    if [[ -f /etc/os-release ]]; then
        . /etc/os-release
        echo "$ID"
    else
        echo "unknown"
    fi
}

# ============================================================================
# Node.js installation
# ============================================================================
install_node() {
    local distro=$(get_distro)
    info "Checking for Node.js..."

    if command -v node &>/dev/null; then
        local current_version=$(node -v | sed 's/v//' | cut -d. -f1)
        if [[ "$current_version" -ge "$NODE_MIN_VERSION" ]]; then
            ok "Node.js $(node -v) already installed."
            return 0
        else
            warn "Node.js $(node -v) found, but version >= ${NODE_MIN_VERSION} required. Upgrading..."
        fi
    fi

    info "Installing Node.js 22.x..."

    case "$distro" in
        ubuntu|debian|pop|linuxmint)
            curl -fsSL https://deb.nodesource.com/setup_22.x | bash - >/dev/null 2>&1
            apt-get install -y nodejs >/dev/null 2>&1
            ;;
        centos|rhel|rocky|almalinux|fedora|amzn)
            if command -v dnf &>/dev/null; then
                curl -fsSL https://rpm.nodesource.com/setup_22.x | bash - >/dev/null 2>&1
                dnf install -y nodejs >/dev/null 2>&1
            else
                curl -fsSL https://rpm.nodesource.com/setup_22.x | bash - >/dev/null 2>&1
                yum install -y nodejs >/dev/null 2>&1
            fi
            ;;
        alpine)
            apk add --no-cache nodejs npm >/dev/null 2>&1
            ;;
        *)
            error "Unsupported distribution: $distro"
            error "Please install Node.js >= ${NODE_MIN_VERSION} manually and re-run."
            exit 1
            ;;
    esac

    if ! command -v node &>/dev/null; then
        error "Failed to install Node.js."
        exit 1
    fi

    ok "Node.js $(node -v) installed."
}

# ============================================================================
# System dependencies
# ============================================================================
install_deps() {
    local distro=$(get_distro)
    info "Installing system dependencies..."

    case "$distro" in
        ubuntu|debian|pop|linuxmint)
            apt-get update -qq >/dev/null 2>&1
            apt-get install -y -qq curl tar python3 make g++ >/dev/null 2>&1
            ;;
        centos|rhel|rocky|almalinux|fedora|amzn)
            if command -v dnf &>/dev/null; then
                dnf install -y -q curl tar python3 make gcc-c++ >/dev/null 2>&1
            else
                yum install -y -q curl tar python3 make gcc-c++ >/dev/null 2>&1
            fi
            ;;
        alpine)
            apk add --no-cache curl tar python3 make g++ >/dev/null 2>&1
            ;;
        *)
            warn "Unknown distribution, skipping system dependency installation."
            ;;
    esac

    ok "System dependencies installed."
}

# ============================================================================
# User and directory setup
# ============================================================================
create_user() {
    info "Creating system user..."
    if id "$AZ_PANEL_USER" &>/dev/null; then
        ok "User '$AZ_PANEL_USER' already exists."
    else
        useradd --system --no-create-home --shell /usr/sbin/nologin "$AZ_PANEL_USER" >/dev/null 2>&1 || \
        useradd --system --no-create-home --shell /sbin/nologin "$AZ_PANEL_USER" >/dev/null 2>&1 || true
        ok "User '$AZ_PANEL_USER' created."
    fi
}

create_dirs() {
    info "Creating directories..."
    mkdir -p "$AZ_PANEL_DIR"
    mkdir -p "$AZ_PANEL_DATA"
    mkdir -p "$AZ_PANEL_DATA/servers"
    mkdir -p "$AZ_PANEL_DATA/backups"
    mkdir -p "$AZ_PANEL_LOG"
    ok "Directories created."
}

# ============================================================================
# Payload extraction
# ============================================================================
extract_payload() {
    info "Extracting AZ PANEL application files..."

    # The payload is a base64-encoded gzip tarball embedded at the end of this script.
    # It is extracted into the install directory.

    local payload_marker="__AZ_PANEL_PAYLOAD_START__"
    local script_path
    script_path=$(readlink -f "$0" 2>/dev/null || echo "$0")

    # Find the payload marker line number
    local marker_line
    marker_line=$(grep -n "^${payload_marker}$" "$script_path" | tail -1 | cut -d: -f1)

    if [[ -z "$marker_line" ]]; then
        error "Payload not found in installer. This installer may be corrupted."
        exit 1
    fi

    # Extract everything after the marker, decode base64, and untar
    tail -n +$((marker_line + 1)) "$script_path" | base64 -d | tar xzf - -C "$AZ_PANEL_DIR"

    if [[ ! -f "${AZ_PANEL_DIR}/server.cjs" ]]; then
        error "Extraction failed - server.cjs not found."
        exit 1
    fi

    ok "Application files extracted."
}

# ============================================================================
# npm dependencies (better-sqlite3 is a native module)
# ============================================================================
install_npm_deps() {
    info "Installing npm dependencies..."
    if [[ ! -f "${AZ_PANEL_DIR}/package.json" ]]; then
        warn "No package.json found, skipping npm install."
        return 0
    fi
    cd "$AZ_PANEL_DIR"
    npm install --production --no-audit --no-fund >/dev/null 2>&1
    if [[ $? -ne 0 ]]; then
        error "npm install failed. Check network connectivity."
        exit 1
    fi
    ok "npm dependencies installed."
}
# ============================================================================
start_panel() {
    if [[ -f "$AZ_PANEL_PID" ]]; then
        local pid=$(cat "$AZ_PANEL_PID")
        if kill -0 "$pid" 2>/dev/null; then
            warn "AZ PANEL is already running (PID: $pid)."
            exit 0
        else
            rm -f "$AZ_PANEL_PID"
        fi
    fi

    info "Starting AZ PANEL on port $AZ_PANEL_PORT..."

    export PORT="$AZ_PANEL_PORT"
    export AZ_DATA_DIR="$AZ_PANEL_DATA"
    export AZ_SERVERS_DIR="$AZ_PANEL_DATA/servers"
    export AZ_BACKUPS_DIR="$AZ_PANEL_DATA/backups"
    export NODE_ENV="production"

    # Generate a random JWT secret on first install
    if [[ ! -f "${AZ_PANEL_DATA}/.jwt_secret" ]]; then
        local secret=$(head -c 48 /dev/urandom | xxd -p | tr -d '\n')
        echo -n "$secret" > "${AZ_PANEL_DATA}/.jwt_secret"
        chmod 600 "${AZ_PANEL_DATA}/.jwt_secret"
    fi
    export AZ_JWT_SECRET=$(cat "${AZ_PANEL_DATA}/.jwt_secret")

    # Start with nohup (no systemd dependency)
    nohup node "${AZ_PANEL_DIR}/server.cjs" > "${AZ_PANEL_LOG}/panel.log" 2>&1 &
    local pid=$!
    echo "$pid" > "$AZ_PANEL_PID"

    sleep 2

    if kill -0 "$pid" 2>/dev/null; then
        ok "AZ PANEL started successfully (PID: $pid)."
        ok "Panel URL: http://$(hostname -I 2>/dev/null | awk '{print $1}' || echo 'localhost'):$AZ_PANEL_PORT"
        ok "Log file: $AZ_PANEL_LOG/panel.log"
    else
        error "AZ PANEL failed to start. Check logs: $AZ_PANEL_LOG/panel.log"
        tail -20 "$AZ_PANEL_LOG/panel.log" 2>/dev/null || true
        exit 1
    fi
}

stop_panel() {
    if [[ ! -f "$AZ_PANEL_PID" ]]; then
        warn "AZ PANEL is not running (no PID file)."
        exit 0
    fi

    local pid=$(cat "$AZ_PANEL_PID")

    if kill -0 "$pid" 2>/dev/null; then
        info "Stopping AZ PANEL (PID: $pid)..."
        kill "$pid" 2>/dev/null || true

        # Wait up to 10 seconds for graceful shutdown
        local count=0
        while kill -0 "$pid" 2>/dev/null && [[ $count -lt 10 ]]; do
            sleep 1
            count=$((count + 1))
        done

        # Force kill if still running
        if kill -0 "$pid" 2>/dev/null; then
            warn "Force killing..."
            kill -9 "$pid" 2>/dev/null || true
        fi

        ok "AZ PANEL stopped."
    else
        warn "AZ PANEL process not found (stale PID file)."
    fi

    rm -f "$AZ_PANEL_PID"
}

status_panel() {
    if [[ -f "$AZ_PANEL_PID" ]]; then
        local pid=$(cat "$AZ_PANEL_PID")
        if kill -0 "$pid" 2>/dev/null; then
            ok "AZ PANEL is running (PID: $pid, port: $AZ_PANEL_PORT)."
            exit 0
        fi
    fi
    warn "AZ PANEL is not running."
    exit 1
}

view_logs() {
    if [[ -f "${AZ_PANEL_LOG}/panel.log" ]]; then
        tail -f "${AZ_PANEL_LOG}/panel.log"
    else
        error "No log file found at ${AZ_PANEL_LOG}/panel.log"
        exit 1
    fi
}

# ============================================================================
# Uninstall
# ============================================================================
uninstall_panel() {
    info "Uninstalling AZ PANEL..."

    # Stop the panel first
    if [[ -f "$AZ_PANEL_PID" ]]; then
        stop_panel 2>/dev/null || true
    fi

    # Ask before deleting data
    echo -e "${YELLOW}Do you want to delete all server data and backups? (y/N)${NC}"
    read -r response
    if [[ "$response" =~ ^[Yy]$ ]]; then
        rm -rf "$AZ_PANEL_DATA"
        info "Server data deleted."
    else
        info "Server data preserved at $AZ_PANEL_DATA"
    fi

    rm -rf "$AZ_PANEL_DIR"
    rm -rf "$AZ_PANEL_LOG"
    rm -f /etc/logrotate.d/az-panel

    # Optionally remove the user
    if id "$AZ_PANEL_USER" &>/dev/null; then
        echo -e "${YELLOW}Remove system user '$AZ_PANEL_USER'? (y/N)${NC}"
        read -r response
        if [[ "$response" =~ ^[Yy]$ ]]; then
            userdel "$AZ_PANEL_USER" 2>/dev/null || true
            ok "User '$AZ_PANEL_USER' removed."
        fi
    fi

    ok "AZ PANEL uninstalled."
}

# ============================================================================
# Post-install setup helper
# ============================================================================
post_install_info() {
    echo ""
    echo -e "${GREEN}========================================${NC}"
    echo -e "${GREEN}  AZ PANEL v${AZ_PANEL_VERSION} installed!${NC}"
    echo -e "${GREEN}========================================${NC}"
    echo ""
    echo -e "Panel URL:   ${CYAN}http://$(hostname -I 2>/dev/null | awk '{print $1}' || echo 'localhost'):${AZ_PANEL_PORT}${NC}"
    echo -e "Data dir:    ${AZ_PANEL_DATA}"
    echo -e "Log file:    ${AZ_PANEL_LOG}/panel.log"
    echo -e "PID file:    ${AZ_PANEL_PID}"
    echo ""
    echo -e "Commands:"
    echo -e "  ${CYAN}$0 start${NC}    - Start the panel"
    echo -e "  ${CYAN}$0 stop${NC}     - Stop the panel"
    echo -e "  ${CYAN}$0 restart${NC}  - Restart the panel"
    echo -e "  ${CYAN}$0 status${NC}   - Check status"
    echo -e "  ${CYAN}$0 logs${NC}     - View logs"
    echo -e "  ${CYAN}$0 uninstall${NC} - Uninstall"
    echo ""
    echo -e "First time? Open the panel URL in your browser to complete setup"
    echo -e "and create your admin account."
    echo ""
}

# ============================================================================
# Logrotate setup
# ============================================================================
setup_logrotate() {
    if [[ -d /etc/logrotate.d ]]; then
        cat > /etc/logrotate.d/az-panel <<LOGROTATE
${AZ_PANEL_LOG}/panel.log {
    daily
    rotate 7
    compress
    missingok
    notifempty
    copytruncate
}
LOGROTATE
        ok "Log rotation configured."
    fi
}

# ============================================================================
# Banner
# ============================================================================
print_banner() {
    echo -e "${CYAN}"
    cat <<'BANNER'
 ##  ####    ###   ##  #  # #### #
#  #   #     #  # #  # ## # #    #
####  #      ###  #### # ## ###  #
#  # #       #    #  # #  # #    #
#  # ####    #    #  # #  # #### ####
BANNER
    echo -e "${NC}"
    echo -e "${GREEN}         Self-Hosted Minecraft / VPS Management Panel${NC}"
    echo -e "                        v${AZ_PANEL_VERSION}"
    echo ""
    echo -e "${CYAN}------------------------------------------------------------${NC}"
    echo ""
}

# ============================================================================
# Install
# ============================================================================
do_install() {
    print_banner
    info "Installing AZ PANEL v${AZ_PANEL_VERSION}..."
    echo ""

    check_root
    install_deps
    install_node
    create_user
    create_dirs
    extract_payload
    install_npm_deps

    # Set ownership
    chown -R "$AZ_PANEL_USER":"$AZ_PANEL_USER" "$AZ_PANEL_DIR"
    chown -R "$AZ_PANEL_USER":"$AZ_PANEL_USER" "$AZ_PANEL_LOG"

    setup_logrotate

    # Start the panel
    start_panel

    post_install_info
}

# ============================================================================
# Main
# ============================================================================
main() {
    local cmd="${1:-}"

    case "$cmd" in
        install)
            do_install
            ;;
        uninstall)
            check_root
            uninstall_panel
            ;;
        start)
            check_root
            start_panel
            ;;
        stop)
            check_root
            stop_panel
            ;;
        restart)
            check_root
            stop_panel 2>/dev/null || true
            sleep 1
            start_panel
            ;;
        status)
            status_panel
            ;;
        logs)
            view_logs
            ;;
        update)
            info "Updating AZ PANEL..."
            check_root
            stop_panel 2>/dev/null || true
            extract_payload
            install_npm_deps
            chown -R "$AZ_PANEL_USER":"$AZ_PANEL_USER" "$AZ_PANEL_DIR"
            start_panel
            ok "AZ PANEL updated."
            ;;
        *)
            echo "AZ PANEL - Self-hosted Minecraft/VPS management panel v${AZ_PANEL_VERSION}"
            echo ""
            echo "Usage: $0 <command>"
            echo ""
            echo "Commands:"
            echo "  install    Install AZ PANEL"
            echo "  uninstall  Remove AZ PANEL"
            echo "  start      Start the panel"
            echo "  stop       Stop the panel"
            echo "  restart    Restart the panel"
            echo "  status     Check if panel is running"
            echo "  logs       View panel logs"
            echo "  update     Update panel with new script"
            exit 1
            ;;
    esac
}

main "$@"
exit 0

